// WF04b step 4 — assemble payload for Apps Script build_xlsx + Telegram summary fields.
// chat_id and callback_url come from the WF03b trigger.
const statements = $('Read Statements by session_id').all().map(i => i.json).filter(s => s && s.session_id);
const transactions = $('Read Transactions by session_id').all().map(i => i.json).filter(t => t && t.session_id);
const categories = $('Read Categories').all().map(i => i.json);
const trigger = $('When called by WF03b').first().json;
const sessionId = trigger.session_id;
const callbackUrl = trigger.callback_url || '';
const targetFolderName = trigger.target_folder_name || '';
const chatId = trigger.chat_id || Number(String(sessionId).split('_')[0]) || 0;
if (statements.length === 0) {
  return [{ json: { error: 'no_statements_for_session', session_id: sessionId, callback_url: callbackUrl, chat_id: chatId } }];
}
const pStarts = statements.map(s => s.period_start).filter(Boolean).sort();
const pEnds = statements.map(s => s.period_end).filter(Boolean).sort();
const periodStart = pStarts[0] || null;
const periodEnd = pEnds.length > 0 ? pEnds[pEnds.length - 1] : null;
const banks = Array.from(new Set(statements.map(s => s.bank).filter(Boolean)));
const currency = statements[0].currency || 'UAH';
let totalDebit = 0, totalCredit = 0, lowConfCount = 0;
const byCategory = {};
transactions.forEach(t => {
  const amt = typeof t.amount === 'number' ? t.amount : (parseFloat(t.amount) || 0);
  if (t.debit_credit === 'debit') totalDebit += amt;
  else if (t.debit_credit === 'credit') totalCredit += amt;
  const conf = typeof t.confidence === 'number' ? t.confidence : (parseFloat(t.confidence) || 0);
  if (conf < 0.8) lowConfCount++;
  const cat = t.category || 'other';
  if (!byCategory[cat]) byCategory[cat] = { debit: 0, credit: 0, count: 0 };
  byCategory[cat].count++;
  if (t.debit_credit === 'debit') byCategory[cat].debit += amt;
  else if (t.debit_credit === 'credit') byCategory[cat].credit += amt;
});
return [{ json: { session_id: sessionId, chat_id: chatId, callback_url: callbackUrl, target_folder_name: targetFolderName, statements, transactions, categories, summary: { period_start: periodStart, period_end: periodEnd, banks, currency, total_debit: totalDebit, total_credit: totalCredit, transactions_count: transactions.length, low_confidence_count: lowConfCount, by_category: byCategory }}}];

// WF04b step 6 — plain-text summary for the Python callback to wrap in Telegram.
const agg = $('Aggregate For XLSX').first().json;
const xlsxResp = $input.first().json;
const xlsxUrl = xlsxResp.xlsx_url || '';
const callbackUrl = agg.callback_url || '';
const s = agg.summary || {};
const sessionId = agg.session_id;
const chatId = Number(agg.chat_id) || 0;
const folderHint = agg.target_folder_name ? ` (Папка: ${agg.target_folder_name})` : '';
const fmt = (n) => (typeof n !== 'number' || isNaN(n)) ? '0' : Math.round(n).toLocaleString('uk-UA').replace(/,/g, ' ');
const pluralTx = (n) => { const mod10 = n % 10, mod100 = n % 100; if (mod10 === 1 && mod100 !== 11) return 'транзакция'; if (mod10 >= 2 && mod10 <= 4 && (mod100 < 10 || mod100 >= 20)) return 'транзакции'; return 'транзакций'; };
const pluralOp = (n) => { const mod10 = n % 10, mod100 = n % 100; if (mod10 === 1 && mod100 !== 11) return 'операція'; if (mod10 >= 2 && mod10 <= 4 && (mod100 < 10 || mod100 >= 20)) return 'операції'; return 'операцій'; };
const banks = (s.banks || []).join(', ') || '?';
const periodStr = `${s.period_start || '?'} – ${s.period_end || '?'}`;
const catNameById = {};
(agg.categories || []).forEach(c => { if (c.id) catNameById[c.id] = c.name_ua || c.id; });
const catEntries = Object.entries(s.by_category || {});
catEntries.sort((a, b) => b[1].debit - a[1].debit);
const top3 = catEntries.slice(0, 3);
const topLines = top3.length === 0 ? '—' : top3.map(([catId, c]) => { const name = catNameById[catId] || catId; return `• ${name}: ${fmt(c.debit)} ${s.currency || 'UAH'} (${c.count} ${pluralOp(c.count)})`; }).join('\n');
let lowConfWarn = '';
if (s.low_confidence_count > 0) lowConfWarn = `\n\n⚠ ${s.low_confidence_count} ${pluralTx(s.low_confidence_count)} требуют проверки (отмечены жёлтым в Excel).`;
const txCount = s.transactions_count || 0;
const summaryText = `Обработано ${txCount} ${pluralTx(txCount)} за период ${periodStr} (${banks})${folderHint}.\n\n💸 Расходы: ${fmt(s.total_debit)} ${s.currency || 'UAH'}\n💰 Доходы: ${fmt(s.total_credit)} ${s.currency || 'UAH'}\n\n📊 Топ-3 категории:\n${topLines}${lowConfWarn}`;
return [{ json: { session_id: sessionId, chat_id: chatId, summary: summaryText, xlsx_url: xlsxUrl, callback_url: callbackUrl, completed_at: new Date().toISOString() }}];
